public static void check(Solution solution) {
    assert Arrays.equals(solution.diStringMatch("DDI"), new int[]{3, 2, 0, 1});
    assert Arrays.equals(solution.diStringMatch("DDIDDI"), new int[]{6, 5, 0, 4, 3, 1, 2});
    assert Arrays.equals(solution.diStringMatch("IDDD"), new int[]{0, 4, 3, 2, 1});
    assert Arrays.equals(solution.diStringMatch("DDDDDDDD"), new int[]{8, 7, 6, 5, 4, 3, 2, 1, 0});
    assert Arrays.equals(solution.diStringMatch("I"), new int[]{0, 1});
    assert Arrays.equals(solution.diStringMatch("IIIIII"), new int[]{0, 1, 2, 3, 4, 5, 6});
    assert Arrays.equals(solution.diStringMatch("D"), new int[]{1, 0});
